#!/usr/bin/env python3
"""Validate frozen generated bytes, then load the v3.2 runner in-process."""

from __future__ import annotations

from pathlib import Path
import hashlib
import runpy
import sys
import time
import types


_HERE = Path(__file__).resolve().parent
if str(_HERE) not in sys.path:
  sys.path.insert(0, str(_HERE))
import validate_superset_graph_bootstrap_v3_2 as bootstrap  # pylint: disable=g-import-not-at-top


def main() -> None:
  generated = bootstrap.validate_generated_bindings_before_import()
  frozen = bootstrap.validate_freeze()
  attestation = types.ModuleType('_opensplice_v3_2_bootstrap_attestation')
  attestation.record = {
      'pid': __import__('os').getpid(),
      'created_at_unix_s': time.time(),
      'generated_bindings': generated,
      'freeze': frozen,
      'launcher_path': str(Path(__file__).resolve()),
      'launcher_sha256': hashlib.sha256(
          Path(__file__).read_bytes()
      ).hexdigest(),
      'bootstrap_path': str(Path(bootstrap.__file__).resolve()),
      'bootstrap_sha256': hashlib.sha256(
          Path(bootstrap.__file__).read_bytes()
      ).hexdigest(),
  }
  sys.modules[attestation.__name__] = attestation
  runpy.run_path(str(_HERE / 'run_superset_graph_v3_2.py'), run_name='__main__')


if __name__ == '__main__':
  main()
